\begin{ex}%[8H3V2]
\immini[thm]{
Cho hình thang cân ${QKHF}$ có $QK // HF$. Lấy ${N}, {M}$ lần lượt là trung điểm của ${QK}$, ${HF}$

 Trong các khẳng định sau khẳng định nào sai?

\choice
{ $QM=KM$  }
   { $\Delta {QMK}$ cân tại ${M}$  }
     { ${ MN}$ là đường cao của hình thang  }
    { \True  $\Delta {QMF}$ cân tại ${M}$  }
}{
\begin{tikzpicture}
            % Define points
            \coordinate (D) at (-2, 0);
            \coordinate (C) at (6, 0);
            \coordinate (B) at (4, 3);
            \coordinate (A) at (0, 3);
            \coordinate (M) at (2, 0);
            \coordinate (N) at (2, 3);
            % Vẽ các cạnh của hình thang
            \draw[thick] (-2,0) -- (6,0) -- (4,3) -- (0,3) -- cycle;
                \draw[thick] (-2,0) -- (4,3);
                \draw[thick] (6,0) -- (0,3);
                 \draw[thick] (M) -- (N);
                 \draw[thick] (M) -- (B)--(A)-- cycle;
    % Gán nhãn cho các điểm
    \node[above left] at (0,3) {$Q$};
            \node[above right] at (4,3) {$K$};
            \node[below right] at (6,0) {$H$};
            \node[below left] at (-2,0) {$F$};
                \node[below] at (M) {$M$};
                  \node[above] at (N) {$N$};
    \end{tikzpicture}
}
\loigiai{
Vì tứ giác ${QKHF}$ là hình thang cân nên ta có ${QF=KH}$ và $\widehat{H}=\widehat{F}$ suy ra $\Delta{QFM}=\Delta{KHM}$ suy ra $QM=KM$ nên $\Delta {QMK}$ cân tại ${M}$.\\
Vì $QM=KM$ nên $\Delta{QMK }$ cân tại ${M}$ suy ra ${MN}$ là trung tuyến đồng thời là đường cao của tam giác nên ${MN} \bot {QK} $ suy ra ${ MN}$ là đường cao của hình thang.Khẳng định sai là: $\Delta {QMF}$ cân tại ${M}$
}\end{ex}

