                \draw[thick] (-2,0) -- (4,3);
                \draw[thick] (6,0) -- (0,3);
                 \draw[thick] (M) -- (N);
                 \draw[thick] (M) -- (B)--(A)-- cycle;
    % Gán nhãn cho các điểm
